import json, random, subprocess, sys, time, ipaddress
sys.path.insert(0, '/workspace/submission')

def ip(x): return str(ipaddress.IPv6Address(x))

def case_tiled(L, nruns, nburst, naddr, cache=12, seed=3):
    """nruns runs tiling the domain: huge spread, mode 2/1 illegal."""
    rng = random.Random(seed)
    step = 1 << (128 - L)
    routes = []
    for k in range(nruns):
        st = k * step
        routes.append([ip(st) + "/" + str(L), k + 1])
    bursts = []
    per = max(1, naddr // max(1, nburst))
    for b in range(nburst):
        addrs = []
        for _ in range(min(per, 64)):
            r = rng.randrange(nruns)
            addrs.append(ip(r * step + rng.randrange(0, step)))
        bursts.append({"version": 0, "repeat": rng.randrange(1, 1000), "addresses": addrs})
    return {"initial": routes, "transactions": [], "bursts": bursts,
            "cache_pages": cache, "costs": {"hit": 2, "miss": 20, "decode": [0, 1, 2]}}

def case_clustered(nruns, nburst, naddr, seed=5):
    rng = random.Random(seed)
    routes = [["::/0", 1]]
    for i in range(1, nruns - 1):
        routes.append([ip(i) + "/128", i + 1])
    bursts = []
    per = max(1, naddr // max(1, nburst))
    for b in range(nburst):
        addrs = []
        for _ in range(min(per, 64)):
            addrs.append(ip(rng.randrange(0, nruns)))
        bursts.append({"version": 0, "repeat": rng.randrange(1, 1000), "addresses": addrs})
    return {"initial": routes, "transactions": [], "bursts": bursts,
            "cache_pages": 12, "costs": {"hit": 2, "miss": 20, "decode": [0, 1, 2]}}

def case_many_versions(nv, rpv, seed=9):
    """nv versions, rpv runs each."""
    rng = random.Random(seed)
    routes = [["::/0", 1]]
    for i in range(1, rpv - 1):
        routes.append([ip(i) + "/128", i + 1])
    txs = []
    cur = dict((r[0], r[1]) for r in routes)
    for t in range(nv - 1):
        ops = []
        for _ in range(3):
            if rng.random() < 0.6:
                ops.append(["set", ip(rng.randrange(0, rpv)) + "/128", rng.randrange(0, 20)])
            else:
                ops.append(["erase", ip(rng.randrange(0, rpv)) + "/128"])
        txs.append(ops)
    bursts = []
    for b in range(64):
        v = rng.randrange(nv)
        addrs = [ip(rng.randrange(0, rpv)) for _ in range(20)]
        bursts.append({"version": v, "repeat": rng.randrange(1, 1000), "addresses": addrs})
    return {"initial": routes, "transactions": txs, "bursts": bursts,
            "cache_pages": 12, "costs": {"hit": 1, "miss": 40, "decode": [0, 1, 2]}}

def run(req, name):
    data = json.dumps({"cases": req}).encode()
    t = time.time()
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    el = time.time() - t
    print('%-24s rc=%d %.1fs out=%d' % (name, p.returncode, el, len(p.stdout)))
    if p.returncode:
        print(p.stderr[:1500]); return None
    try:
        r = json.loads(p.stdout)
    except Exception as e:
        print('BAD JSON', p.stdout[:200]); return None
    if 'cases' not in r:
        print('invalid response', p.stdout[:200]); return None
    print('   objectives', [c['objective'] for c in r['cases']])
    return r

if __name__ == '__main__':
    which = sys.argv[1]
    if which == 'spread':
        run([case_tiled(6, 64, 128, 4000)], 'spread R=64')
    elif which == 'both':
        run([case_tiled(6, 64, 64, 2000), case_clustered(64, 64, 2000)], 'two cases R=64+64')
    elif which == 'vers':
        run([case_many_versions(8, 16)], '8 versions x16 runs')
    elif which == 'vers4':
        run([case_many_versions(8, 16), case_many_versions(2, 32, 11),
             case_clustered(16, 32, 1000), case_tiled(4, 16, 32, 1000)], '4 cases max')
    elif which == 'burst':
        c = case_clustered(64, 256, 8192)
        run([c], 'max bursts')
